 r1 = 1                             | r1 = 1                                     | r1 = load_acquire((u32 *)(r2 + 0)) ;
 *(u32 *)(r2 + 0) = r1              | r3 = atomic_fetch_add((u32 *)(r2 + 0), r1) | r3 = *(u32 *)(r4 + 0)              ;
 r3 = 1                             |                                            |                                    ;
